<script setup>
import { ref, computed } from 'vue';
import Icon from '../components/Icon.vue';
import Modal from '../components/Modal.vue';
import { state, isDemo, nav, notify, refresh } from '../lib/workspace.js';
import { post } from '../lib/api.js';
const keyword = ref(''), dialog = ref(''), tag = ref(''), files = ref([]), dragging = ref(false), picker = ref(), busy = ref(false), error = ref('');
const repoUrl = ref(''), username = ref(''), password = ref('');
const visible = computed(() => state.rags.filter(r => r.ragTag?.toLowerCase().includes(keyword.value.toLowerCase())));
function open(mode) { dialog.value = mode; error.value = ''; files.value = []; tag.value = ''; }
function addFiles(list) { const unique = new Map(files.value.map(f => [f.name + f.size + f.lastModified, f])); for (const file of list) unique.set(file.name + file.size + file.lastModified, file); files.value = [...unique.values()]; }
function drop(event) { dragging.value = false; addFiles(event.dataTransfer.files); }
async function upload() {
  if (busy.value) return;
  if (dialog.value === 'file' && (!tag.value.trim() || !files.value.length)) { error.value = '请输入知识库名称，并选择至少一个文件'; return; }
  if (dialog.value === 'git') { try { const url = new URL(repoUrl.value); if (!['https:', 'http:'].includes(url.protocol)) throw new Error(); } catch { error.value = '请输入有效的 HTTP 或 HTTPS 仓库地址'; return; } }
  busy.value = true; error.value = '';
  try {
    if (isDemo.value) { const name = dialog.value === 'file' ? tag.value.trim() : repoUrl.value.split('/').filter(Boolean).pop().replace(/\.git$/, ''); if (!state.rags.some(r => r.ragTag === name)) state.rags.push({ ragTag: name }); notify('已添加演示知识库，未上传或解析任何文件'); }
    else { if (dialog.value === 'file') { const form = new FormData(); form.append('ragTag', tag.value.trim()); files.value.forEach(file => form.append('fileList', file)); await post('/ai/rag/file', { form }); } else await post('/ai/rag/git', { json: { repoUrl: repoUrl.value, username: username.value, password: password.value } }); await refresh(); notify('导入请求已完成，请检查知识标签；文件批次可能仅部分成功'); }
    password.value = ''; files.value = []; dialog.value = '';
  } catch (e) { error.value = e.message; } finally { busy.value = false; }
}
const size = n => n < 1024 * 1024 ? Math.ceil(n / 1024) + ' KB' : (n / 1024 / 1024).toFixed(1) + ' MB';
</script>
<template>
  <div class="page"><header class="page-heading"><div><div class="eyebrow">YOUR KNOWLEDGE, CONNECTED</div><h1>让 AI 更懂你的世界</h1><p>把文档、笔记和代码，变成随时可用的知识。</p></div><button class="primary-button" @click="open('file')"><Icon name="plus" :size="17" />导入知识</button></header>
    <section class="knowledge-intro"><div class="knowledge-illustration" aria-hidden="true"><span class="paper-illustration paper-back"><Icon name="code" :size="42" /></span><span class="paper-illustration paper-front"><Icon name="file" :size="36" /><i></i><i></i><i></i></span><span class="knowledge-spark">✳</span></div><div><span class="eyebrow">A SECOND BRAIN FOR YOUR AI</span><h2>你的积累，<br />都可以成为新的起点。</h2><p>在对话中关联知识库，让回答拥有你的上下文。</p><div class="row"><button class="secondary-button" @click="open('file')"><Icon name="upload" :size="16" />上传文件</button><button class="text-button" @click="open('git')"><Icon name="code" :size="16" />导入 Git 仓库 <Icon name="arrow" :size="15" /></button></div></div></section>
    <div class="toolbar"><h2 class="subheading">我的知识库 <span class="count">{{ state.rags.length }}</span></h2><div class="search-field"><Icon name="search" :size="16" /><input v-model="keyword" placeholder="查找知识库" aria-label="搜索知识库" /></div></div><div v-if="isDemo" class="demo-notice"><i class="tiny-dot"></i>当前展示示例知识标签，实际内容将在登录后读取</div><div v-if="visible.length" class="knowledge-grid"><article v-for="(rag, index) in visible" :key="rag.ragTag" class="knowledge-card"><div class="row spread"><span class="agent-avatar" :class="['sage','peach','lavender'][index % 3]"><Icon name="book" :size="24" /></span><span class="tag sage">{{ isDemo ? '示例知识库' : '知识标签' }}</span></div><h3>{{ rag.ragTag }}</h3><p>连接你的资料，为每一次对话补充背景。</p><footer><span><Icon name="layers" :size="14" />可用于对话检索</span><button class="text-button" @click="nav('chat', { rag: rag.ragTag })">开始对话 <Icon name="arrow" :size="16" /></button></footer></article></div><div v-else class="empty-state"><Icon name="book" :size="42" /><h2>{{ keyword ? '没有找到这份知识' : '把你的第一份资料放进来' }}</h2><p>导入文档、笔记或 Git 仓库，让 AI 获得更多上下文。</p><button class="secondary-button" @click="open('file')">导入知识</button></div>
    <div class="knowledge-notes"><div><Icon name="file" :size="20" /><h3>从日常资料开始</h3><p>文档、Markdown、文本等格式，实际支持情况取决于服务端解析器。</p></div><div><Icon name="shield" :size="20" /><h3>属于你的知识空间</h3><p>知识按用户隔离。在需要时关联，在对话中使用。</p></div><div><Icon name="chat" :size="20" /><h3>在上下文中找到答案</h3><p>进入自由对话，从会话选项中选择需要关联的知识库。</p></div></div>
  </div>
  <Modal v-if="dialog" :title="dialog === 'file' ? '给 AI 一点你的知识' : '从代码仓库开始'" @close="!busy && (dialog = '', password = '')"><form class="modal-body form-stack" @submit.prevent="upload"><template v-if="dialog === 'file'"><label>知识库名称<input v-model="tag" required placeholder="例如：产品与设计资料" /></label><div class="dropzone" :class="{ dragging }" @dragover.prevent="dragging = true" @dragleave.prevent="dragging = false" @drop.prevent="drop"><Icon name="upload" :size="31" /><strong>把文件拖到这里</strong><span>或者<button type="button" class="text-button" @click="picker.click()">点击选择文件</button></span><small>支持多文件；解析与大小限制以服务端配置为准。</small><input ref="picker" type="file" multiple class="sr-only" aria-label="选择知识文件" @change="addFiles($event.target.files)" /></div><div v-if="files.length" class="upload-file-list"><div v-for="(file, index) in files" :key="file.name + index"><Icon name="file" :size="18" /><span>{{ file.name }}<small>{{ size(file.size) }}</small></span><button type="button" class="icon-button" aria-label="移除文件" :disabled="busy" @click="files.splice(index, 1)"><Icon name="close" :size="15" /></button></div></div><p class="small muted">导入会同步切分与向量化，请耐心等待。批量导入成功不代表每个文件都解析成功。</p></template><template v-else><label>Git 仓库地址<input v-model="repoUrl" type="url" required placeholder="https://github.com/team/project.git" /></label><label>用户名 · 可选<input v-model="username" autocomplete="off" placeholder="私有仓库的访问用户名" /></label><label>访问令牌 · 可选<input v-model="password" type="password" autocomplete="off" placeholder="需要认证时填写" /></label><div class="info-note">知识库名称从仓库地址生成。当前会采集 Java、HTML、Markdown 和文本文件，跳过隐藏目录。</div></template><div v-if="isDemo" class="info-note">演示模式仅添加示例标签，不会上传文件或克隆仓库。</div><div v-if="error" class="form-error">{{ error }}</div><button class="primary-button" :disabled="busy"><Icon :name="busy ? 'refresh' : 'upload'" :size="17" />{{ busy ? '正在导入，请稍候…' : isDemo ? '添加演示知识库' : '开始导入' }}</button></form></Modal>
</template>
